//!   not need queue state (SPEC section 2, steps 1 to 3).
//! - [`service`] holds all queues and the virtual clock and executes requests.
//! - [`protocol`] glues the two together: one input line in, one response line out.

pub mod error;

pub use error::{Error, ErrorCode};
