fn send_message_rules() {
    let mut s = Session::new();
    s.create("q", json!({}));
    s.create("f.fifo", json!({"Fifo": true}));
    s.create("c.fifo", json!({"Fifo": true, "ContentBasedDeduplication": true}));
    let send = |queue: &str, extra: Value| {
        let mut command = json!({"Command": "SendMessage", "QueueName": queue, "Body": "b"});
        for (k, v) in extra.as_object().unwrap() {
            command[k] = v.clone();
        }
        command
    };
    assert_eq!(s.err(send("q", json!({"DeduplicationId": "d"}))), "UnsupportedOperation");
    assert_eq!(
        s.err(send("f.fifo", json!({"DelaySeconds": 0, "GroupId": "g"}))),
        "UnsupportedOperation"
    );
    assert_eq!(s.err(send("f.fifo", json!({"DeduplicationId": "d"}))), "MissingParameter");
    assert_eq!(s.err(send("f.fifo", json!({"GroupId": "g"}))), "MissingParameter");
    assert_eq!(s.ok(send("c.fifo", json!({"GroupId": "g"})))["SequenceNumber"], 1);
    // Content-based deduplication uses the body, whatever the group.
    assert_eq!(
        s.ok(send("c.fifo", json!({"GroupId": "other"}))),
        json!({"ok": true, "MessageId": "m-1", "SequenceNumber": 1})
    );
    assert_eq!(s.err(send("nope", json!({"GroupId": "g"}))), "QueueDoesNotExist");
