    assert_eq!(responses[0]["Now"], 1);
    assert_eq!(responses[1]["error"]["code"], "InvalidRequest");
    assert_eq!(responses[2]["error"]["code"], "InvalidRequest");
    assert_eq!(responses[3]["Now"], 3);
}

